from collections.abc import Iterable
from dataclasses import dataclass


@dataclass(frozen=True)
class Item:
    sku: str
    quantity: int
    discontinued: bool = False


def inventory_summary(
    items: Iterable[Item], include_discontinued: bool = False
) -> dict[str, int]:
    """Return the count and units for currently available inventory."""
    count = 0
    units = 0
    for item in items:
        if item.quantity <= 0 or (item.discontinued and not include_discontinued):
            continue
        count += 1
        units += item.quantity

    return {"count": count, "units": units}

from src.inventory import Item, inventory_summary


def test_default_behavior():
    assert inventory_summary([Item("active", 2), Item("old", 3, discontinued=True)]) == {
        "count": 1,
        "units": 2,
    }


def test_include_discontinued_accepts_one_shot_iterable_and_filters_non_positive_stock():
    items = (
        item
        for item in [
            Item("active", 2),
            Item("old", 3, discontinued=True),
            Item("empty", 0),
            Item("negative", -1),
            Item("old-empty", 0, discontinued=True),
            Item("old-negative", -2, discontinued=True),
        ]
    )

    assert inventory_summary(items, include_discontinued=True) == {
        "count": 2,
        "units": 5,
    }

